// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz parameters:
    // - addrIsGood: decides whether we pass a callee implementing the correct selector or a callee that will cause a failed call for the wrong selector
    // - from: arbitrary from address passed through
    // - v0: an arbitrary uint value used in the values array
    function testFuzz_property(bool addrIsGood, address from, uint256 v0) public {
        // keep wide domain but avoid the zero-address for callee and ensure non-zero _tos length by constructing arrays with one element
        address callee;
        if (addrIsGood) {
            callee = address(new RecorderGood());
        } else {
            callee = address(new RecorderBad());
        }

        // prepare single-element arrays so loop runs exactly once (avoids accumulation complexity)
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF); // recipient arg inside the encoded call; can be arbitrary
        uint256[] memory vals = new uint256[](1);
        vals[0] = v0;

        // call transfer and observe whether it reverts
        bool ok;
        try c.transfer(from, callee, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on the REFERENCE contract, when the callee implements the correct selector (RecorderGood), c.transfer MUST succeed (ok == true) for any inputs with non-empty _tos.
        // The mutant that uses a wrong selector will make the call fail against RecorderGood (because it expects the correct selector), causing ok==false for some inputs.
        // We therefore assert that when we deploy the good callee, c.transfer does not revert.
        if (addrIsGood) {
            assertTrue(ok);
        }
        // If addrIsGood == false (we passed RecorderBad), we do not assert anything — we only require the property to hold for all inputs when the callee implements the expected selector.
    }
}

// A helper that implements the exact function signature the correct C expects and always returns true when called.
contract RecorderGood {
    // Matches: transferFrom(address,address,uint256)
    event Recorded(address from, address to, uint256 v);
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Recorded(from, to, v);
        return true;
    }
}

// A helper that does NOT implement the expected 3-arg selector; implements a different signature so a call with the correct selector will fail
contract RecorderBad {
    // Different arity: four args so selector differs from the expected one in the reference
    event RecordedBad(address a, address b, address c, uint256 v);
    function transferFrom(address a, address b, address c, uint256 v) external returns (bool) {
        emit RecordedBad(a,b,c,v);
        return true;
    }
}
